    for e in d["functions"]:
        if e["fn"].split(sep)[-1] == "dyn_head":
            return e.get("cmds", [])
    return []
print("\n[4d] EXEC-HEAD differential  (SPEC §4 — a dynamic head's argument literal must NOT become `cmds`)")
engines = [("rust", sys.argv[1], "::"), ("java", sys.argv[2], ".")]
