try:
    fns = json.load(open(sys.argv[1]))["functions"]
    ok = any(e.get("unitKind") == "export" for e in fns)
    print("  ts         CJS export unit -> export" if ok else "  ts         WARN (unitKind absent — draft)")
except Exception as e:
    print(f"  ts         WARN ({e})")
PY
fi
if [ -n "$SW_BIN" ] && [ -x "$SW_BIN" ]; then
