  ( cd "$FS/sw" && "$SW_BIN" Tests/Helper.swift --out t >/dev/null 2>&1 )
  python3 "$HERE/file_set_check.py" "swift" "$s48e" "$(ls "$FS"/sw/e.*.Swift.json 2>/dev/null | grep -vE 'callgraph|hierarchy|locs' | head -1)" \
