    if [ "$arm" = dirty ]; then printf 'import Foundation\nfunc spawn() { let p = Process(); p.launchPath = "/bin/ls"; try? p.run() }\n' > "$d/Tests/T.swift"
    else printf 'import Foundation\nfunc harmless() -> Int { 42 }\n' > "$d/Tests/T.swift"; fi
