    P79_OUT="$P79_OUT  $1  got=$2  OK
"
  else
    P79_OUT="$P79_OUT  $1  got=$2 want=$3  FAIL
"
    P79_BAD=1; rc=1
  fi
}
P79_BAD=0; P79_OUT=""
P79="$W/p79"
