  P80G_ENG="$1"; P80G_VAR="$2"; P80G_REP="$3"; P80G_FRAG="$4"; shift 4
  P80G_TXT="${P80G_FRAG}.txt"; P80G_GJ="${P80G_FRAG}.gate.json"
