json.dump({"engine": sys.argv[1], "variant": sys.argv[2], "exit": int(sys.argv[3]),
           "text_file": sys.argv[4], "gate_json": sys.argv[5]}, open(sys.argv[6], "w"))
' "$P80G_ENG" "$P80G_VAR" "$P80G_RC" "$P80G_TXT" "$P80G_GJ" "${P80G_FRAG}.meta.json"
}
